-- D7928 (#7928): the BLS Consumer Expenditure Surveys source (all consumer units, United States) and its catalogue:
-- for nine spending categories, the mean annual expenditure per consumer unit, its standard error and its coefficient
-- of variation. Data only: one source row and 27 catalogue rows. No observation is seeded; rows arrive only through the
-- operator import (D7709). The source lands DISABLED: #7928 authorises no live activation, and bls.gov could not be
-- read from the session that wrote this (D7928), so the provider terms and the table layout must be confirmed before
-- an owner enables it. export_allowed stays unset (D7716: export is a per-source owner decision).
-- forward-fix: cloudflare-worker/sql/forward-fixes/202611270444_7928_bls_ce_source.fix.sql
INSERT OR IGNORE INTO research_market_sources
(id, name, source_url, dataset_or_edition, methodology_url, license_or_usage_note, refresh_policy, enabled)
VALUES
('bls-ce', 'U.S. Bureau of Labor Statistics Consumer Expenditure Surveys (all consumer units)',
 'https://www.bls.gov/cex/tables/calendar-year/mean-item-share-average-standard-error.htm',
 'Consumer Expenditure Surveys, calendar-year table of means, standard errors and coefficients of variation, All consumer units column, calendar years 2023 to 2025',
 'https://www.bls.gov/opub/hom/cex/calculation.htm',
 'Source: U.S. Bureau of Labor Statistics, Consumer Expenditure Surveys, calendar-year standard-error table, retrieved on each row''s retrieval date. BLS material is generally in the public domain as a work of the U.S. Government; the formal terms were not read when this source was registered (D7928) and must be confirmed before it is enabled. Values are not modified. Not endorsed by BLS. Limitations: means per consumer unit, not per household or per person; sample estimates with sampling error, whose published standard error and coefficient of variation are stored beside each mean; cells BLS suppresses (relative standard error of 25 percent or more, from the 2023 tables) store no row.',
 'annual', 0);

